/// <summary>
/// CB167_PerformStockReservation
/// This class <c>METStockReservation</c> contains the logic to reserve stocks.
/// </summary>
class METStockReservation
{
    SalesTable        salesTable;
    CompanyInfo       companyInfo;
    METCustParameters metCustParameters;
    CustGroupId       custGroupId;
    boolean           pickPartialReservedLine;
    boolean           lineSubstituted;

}

Method.Source:
/// <summary>
/// Gets/sets Salestable.
/// </summary>
/// <param name = "_salesTable">Salestable.</param>
/// <returns>Salestable.</returns>
public SalesTable parmSalesTable(SalesTable _salesTable = salesTable)
{
    salesTable = _salesTable;
    return salesTable;
}

/// <summary>
/// Gets Customer group.
/// </summary>
/// <returns>Customer group.</returns>
private CustGroupId getCustGroupId()
{
    if (!custGroupId)
    {
        custGroupId = salesTable.custTable_CustAccount().CustGroup;
    }

    return custGroupId;
}

/// <summary>
/// Constructs and returns <c>METStockReservation</c>.
/// </summary>
/// <param name = "_salesTable">
/// <c>SalesTable</c>.
/// </param>
/// <returns>
///  <c>METStockReservation</c>.
/// </returns>
public static METStockReservation construct(SalesTable _salesTable)
{
    METStockReservation stockReservation;

    stockReservation = new METStockReservation();

    stockReservation.parmSalesTable(_salesTable);
    stockReservation.init();

    return stockReservation;
}

/// <summary>
/// Initializes the class variables.
/// </summary>
private void init()
{
    metCustParameters = METCustParameters::Find();
    companyInfo = CompanyInfo::find();
}

/// <summary>
/// CB167_PerformStockReservation
/// Executes the stock reservation process.
/// </summary>
public void process()
{
    try
    {
        ttsbegin;

        //Reserves stock.
        this.reserveStock();
        //Optimises sales order.
        this.optimiseSalesOrder();
        //Re-reserves after sales order optimization.
        this.reserveStock();
        //Ends process update
        this.endProcess();


        ttscommit;
    }
    catch 
    {
        throw error("@MET:METStockReservationError");
    }

}

/// <summary>
/// CB167_PerformStockReservation
/// Reserves stock against the sales order.
/// </summary>
private void reserveStock()
{
    pickPartialReservedLine = false;

    switch (companyInfo.METLegalEntityType)
    {
        case METLegalEntityType::Food:
            this.reserve();

            break;
        case METLegalEntityType::Liquor:

            pickPartialReservedLine = true;

            this.reserve();

            break;
    }
}

/// <summary>
/// CB167_PerformStockReservation
/// Optimises sales order.
/// </summary>
private void optimiseSalesOrder()
{
    this.substituteSalesLine();
}

/// <summary>
/// CB167_PerformStockReservation
/// Reserves quantity against sales lines.
/// </summary>
private void reserve()
{
    SalesLine             salesLine;
    METSalesLine          metSalesLine;

    while select QtyOrdered, InventTransId from salesLine
        where salesLine.SalesId     == salesTable.SalesId
        &&    salesLine.SalesStatus == SalesStatus::Backorder
    exists join metSalesLine
        where metSalesLine.SalesLine == salesLine.RecId
        &&    (metSalesLine.ReasonId  != METConstants::NIRReasonCode
        ||     metSalesLine.ReasonId  != METConstants::NewReasonCode)
    {
        METInventTransReserveService reserveService = METInventTransReserveService::construct(salesLine.InventTransId, salesLine.QtyOrdered);
        reserveService.parmPickPartialReservedLine(pickPartialReservedLine);
        reserveService.reserve();
    }
}

/// <summary>
/// CB167_PerformStockReservation/
/// Substitutes sales lines.
/// </summary>
private void substituteSalesLine()
{
    METSubstitutionSalesLineProcess subSalesLineProcess;
    SalesLine                       salesLine;
    METSalesLine                    metSalesLine;

    while select salesLine
        where salesLine.SalesId     == salesTable.SalesId
        &&    salesLine.SalesStatus == SalesStatus::Backorder
    exists join metSalesLine
        where metSalesLine.SalesLine == salesLine.RecId
        &&    (metSalesLine.ReasonId  != METConstants::NIRReasonCode
        ||     metSalesLine.ReasonId  != METConstants::NewReasonCode)
    {
        if (!salesLine.mcrSalesQtyReserved())
        {
            subSalesLineProcess = METSubstitutionSalesLineProcess::construct(salesLine);

            if (subSalesLineProcess.run() && !lineSubstituted)
            {
                lineSubstituted = true;
            }
        }
    }

}

/// <summary>
/// Processing at the end.
/// </summary>
private void endProcess()
{
    if (lineSubstituted)
    {
        ttsbegin;
        METSalesTable metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId, true);
        if (metSalesTable)
        {
            metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::ReadyForPricing;
            metSalesTable.update();
        }
        ttscommit;

        // Step 4: Call TMS engine
        if (metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::ReadyForPricing)
        {
            METTMSEngineSalesOrderProccess  metTMSEngineSalesOrderProccess = METTMSEngineSalesOrderProccess::construct(METTMSEngineSalesOrderProcess::Creation, salesTable);
            metTMSEngineSalesOrderProccess.run();
        }
    }

}
